# Run from the book repository: Rscript scripts/generate-tukey-critical-values.R
# https://stat.ethz.ch/R-manual/R-devel/library/stats/html/Tukey.html
# Keep quantiles at four decimal places, the documented accuracy of qtukey.
dfs <- c(2:30, 40, 60, 120, Inf)
ks <- 2:10
lines <- c(
  '// Generated by scripts/generate-tukey-critical-values.R using R stats::qtukey.',
  '// For k = 2, use the exact sqrt(2) * qt(1 - alpha/2, df) identity.',
  '// Keys are alpha, then error df; each row contains k = 2 through 10.',
  '// No interpolation: unsupported table coordinates are rejected.',
  'window.sfsTukeyCriticalValues = {'
)
for (alpha in c(.05, .01)) {
  lines <- c(lines, sprintf('  "%s": {', alpha))
  for (i in seq_along(dfs)) {
    values <- qtukey(1 - alpha, nmeans = ks, df = dfs[i])
    # Avoid qtukey's numerical error at very small df for the two-mean case.
    values[1] <- sqrt(2) * qt(1 - alpha / 2, df = dfs[i])
    stopifnot(all(is.finite(values)))
    lines <- c(lines, sprintf('    "%s": [%s]%s', as.character(dfs[i]),
      paste(sprintf('%.4f', values), collapse = ', '), if (i < length(dfs)) ',' else ''))
  }
  lines <- c(lines, if (alpha == .05) '  },' else '  }')
}
writeLines(c(lines, '};'), 'resources/js/tukey-critical-values.js')
